def _compute_nodes_in_community(self) -> List[np.ndarray]:
  """Returns a list `communities`, such that communities[k] contains the
  indices of nodes in community k.
  """

  communities = [np.where(self.z == k)[0] for k in range(self.K)]
  return communities


