def patch_tqdm_notebook(src, cell_idx, log):
    """tqdm.notebook / tqdm.auto resolve to the ipywidgets bar, which raises
    ImportError at *instantiation* time in a headless run (the import itself
    succeeds, so a try/except around the import is not enough).  tqdm.std.tqdm
    wraps the very same iterator, so the numeric logic is untouched."""
    for old in ("from tqdm.notebook import tqdm", "from tqdm.auto import tqdm"):
        if old in src:
            log.append(
                f"cell {cell_idx}: replaced `{old}` with plain `from tqdm import tqdm` "
                "(progress display only, no numeric effect)"
            )
            src = src.replace(old, "# patched by extract_authors_notebook.py\nfrom tqdm import tqdm")
    return src

